sys_properties.value:
[
  {
    "kpi": "Usage Mapped to Inactive Users",
    "description": "The software installation with active CI usage is mapped to a user account that is marked as inactive.",
    "table": "cmdb_sam_sw_install",
    "query": "assigned_to.active=false"
  },
  {
    "kpi": "Incorrect User Mapping",
    "description": "The user mapped for software usage does not match the 'Assigned To' user of the associated CI.",
    "table": "samp_sw_usage",
    "query": "userNSAMEASconfiguration_item.assigned_to"
  },
  {
    "kpi": "Outdated Installations",
    "description": "Software installations that have not been scanned for more than 90 days, indicating outdated or inactive installations.",
    "table": "cmdb_sam_sw_install",
    "query": "last_scanned<javascript:gs.beginningOfLast3Months()"
  },
  {
    "kpi": "Inaccurate Installations",
    "description": "Software installations without Publisher, Product, Version.",
    "table": "samp_sw_usage",
    "query": "publisherISEMPTY^ORnorm_productISEMPTY^ORversionISEMPTY"
  }
]
